SELECT
    MIN(line_id) AS min_line_id,
    MAX(line_id) AS max_line_id
FROM (
    SELECT d.line_id AS line_id
    FROM DAILY_APP_TOTAL_DATA d
    WHERE d.usage_date >= #{startInclusive}
      AND d.usage_date < #{endExclusive}
      AND d.deleted_at IS NULL
    UNION ALL
    SELECT t.line_id AS line_id
    FROM TRAFFIC_DEDUCT_DONE t
    WHERE t.enqueued_at >= #{startDateTimeInclusive}
      AND t.enqueued_at < #{endDateTimeExclusive}
) restore_line_source
